  return new Promise((resolve) => {
    const list = events.get(method) ?? []
    list.push(resolve)
    events.set(method, list)
    setTimeout(() => resolve(undefined), timeoutMs)
  })
}

await send('Page.enable')
await send('Runtime.enable')
await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false })

for (const target of targets) {
  const [url, settleArg, expression] = target.split('::')
  const settle = Number(settleArg ?? 8000)
  logs.length = 0
  const loaded = once('Page.loadEventFired')
  await send('Page.navigate', { url })
  await loaded
  await sleep(settle)
  if (expression) {
    const result = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })
    if (result?.exceptionDetails) console.log(url, 'ERROR', JSON.stringify(result.exceptionDetails).slice(0, 400))
    else console.log(url, '=>', JSON.stringify(result?.result?.value))
  }
  for (const line of logs) console.log('  console:', line.slice(0, 300))
}

ws.close()
chrome.kill('SIGKILL')
process.exit(0)

