import { Canvas, useFrame } from '@react-three/fiber'
import { Bloom, ChromaticAberration, EffectComposer, Vignette } from '@react-three/postprocessing'
import { BlendFunction } from 'postprocessing'
import { useMemo, useRef, type ReactNode } from 'react'
import { Vector2 } from 'three'
import { usePrefersReducedMotion } from '@/deck/motion'

// TEMPORARY frame-time instrument; removed before commit.
function FrameMeter(): null {
  const state = useRef({ frames: 0, start: 0, done: false })
  useFrame(() => {
    const s = state.current
    if (s.done) return
    const now = performance.now()
    if (s.start === 0) { s.start = now; return }
    s.frames += 1
    if (now - s.start >= 5_000) {
      s.done = true
      const avg = (now - s.start) / s.frames
      const line = `frame-meter avg ${avg.toFixed(2)} ms over ${s.frames} frames`
      console.log(line)
      ;(window as unknown as { __deckFrameMs?: number }).__deckFrameMs = avg
    }
  })
  return null
}

