// TEMPORARY frame-time instrument; removed before commit.
function FrameMeter(): null {
  const state = useRef({ samples: [] as number[], start: 0, last: 0, done: false })
  useFrame(() => {
    const s = state.current
    if (s.done) return
    const now = performance.now()
    if (s.start === 0) { s.start = now; s.last = now; return }
    s.samples.push(now - s.last)
    s.last = now
    if (now - s.start >= 5_000) {
      s.done = true
      const sorted = [...s.samples].sort((a, b) => a - b)
      const mean = s.samples.reduce((sum, value) => sum + value, 0) / s.samples.length
      const min = sorted[0] ?? 0
      const p50 = sorted[Math.floor(sorted.length / 2)] ?? 0
      console.log(
        `frame-meter n=${s.samples.length} min ${min.toFixed(1)} p50 ${p50.toFixed(1)} mean ${mean.toFixed(1)} ms`,
      )
      ;(window as unknown as { __deckFrameMs?: [number, number, number] })
        .__deckFrameMs = [min, p50, mean]
    }
  })
  return null
}

