    rgba(4, 6, 11, 0.8) 0%,
    rgba(4, 6, 11, 0.46) 46%,
    rgba(4, 6, 11, 0) 80%
  );
  opacity: 1;
  transition: opacity 520ms ease;
}

.title-card[data-state='out'] { opacity: 0; }

