.badge[data-mode='live'] .badge__dot { animation: pulse 2s ease-in-out infinite; }

/*
 * Only a live feed sweeps. Replay is a fixed recording, so its badge holds
 * still in amber and nothing about it suggests something is arriving.
 */
.badge[data-mode='live'] .badge__dot::after {
  content: '';
  position: absolute;
  inset: -1px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0;
  animation: radar 2s cubic-bezier(0.16, 0.84, 0.44, 1) infinite;
}

.badge[data-mode='replay'] .badge__dot { animation: none; }

@keyframes pulse {
  0%, 100% { opacity: 1; box-shadow: 0 0 0 0 currentColor; }
  50% { opacity: 0.55; box-shadow: 0 0 0 4px rgba(73, 224, 166, 0); }
}

@keyframes radar {
  0% { transform: scale(1); opacity: 0.8; }
  70% { opacity: 0; }
  100% { transform: scale(4.4); opacity: 0; }
}

